#stage { --ground:#0F172A; --main:#60A5FA; --second:#E2E8F0; --accent:#34D399; --ink:color-mix(in srgb, var(--second) 95%, transparent); --ink2:color-mix(in srgb, var(--second) 62%, transparent); --ink3:color-mix(in srgb, var(--second) 38%, transparent); --panel:color-mix(in srgb, var(--ground) 84%, var(--second)); --panel2:color-mix(in srgb, var(--ground) 91%, var(--second)); --line:color-mix(in srgb, var(--second) 10%, transparent); --line2:color-mix(in srgb, var(--second) 21%, transparent); color:var(--ink); font-family:var(--sans, system-ui, "PingFang SC", "Microsoft YaHei", sans-serif) }
.ground { position:absolute; inset:0; background:var(--ground) }
.desk-light { position:absolute; inset:0; background:radial-gradient(56% 42% at 50% 68%, color-mix(in srgb, var(--main) 13%, transparent), transparent 72%) }
.desk-vig { position:absolute; inset:0; background:radial-gradient(118% 96% at 50% 44%, transparent 44%, rgba(0,0,0,.66)) }
.desk-ticks { position:absolute; left:54px; top:0; bottom:0; width:16px; background-image:repeating-linear-gradient(to bottom, color-mix(in srgb, var(--second) 15%, transparent) 0 1px, transparent 1px 48px) }
.words { position:absolute; margin:0; display:flex; flex-direction:column; gap:14px }
.title { font-family:var(--display, var(--sans, system-ui, sans-serif)); font-size:52px; line-height:1.2; font-weight:600; letter-spacing:.01em }
.sub { font-size:26px; line-height:1.4; color:var(--ink2) }
.mono { font-family:ui-monospace, SFMono-Regular, Menlo, monospace }
